use std::cell::RefCell;
use std::rc::Rc;

trait Device {
    fn press(&self, log: &RefCell<Vec<String>>);
}

struct Tv;
struct Fan {
    speed: u32,
}

impl Device for Tv {
    fn press(&self, log: &RefCell<Vec<String>>) {
        log.borrow_mut().push("tv on".to_string());
    }
}

impl Device for Fan {
    fn press(&self, log: &RefCell<Vec<String>>) {
        log.borrow_mut().push(format!("fan {}", self.speed));
    }
}

impl Drop for Fan {
    fn drop(&mut self) {
        println!("fan unplugged");
    }
}

fn main() {
    let log = Rc::new(RefCell::new(Vec::new()));
    let copy = Rc::clone(&log);
    {
        let remote: Vec<Box<dyn Device>> =
            vec![Box::new(Fan { speed: 2 }), Box::new(Tv)];
        for d in remote.iter().rev() {
            d.press(&copy);
        }
        println!("pressed {}", log.borrow().len());
    }
    println!("{:?}", copy.borrow());
    println!("owners {}", Rc::strong_count(&log));
}

