fn main() {
    let book = Rc::new("Dune");
    let mut readers: Vec<Rc<&str>> = Vec::new();
    let mut bookmarks: Vec<Weak<&str>> = Vec::new();
    for step in 1..=4 {
        if step % 2 == 1 {
            readers.push(Rc::clone(&book));
