trait Shape {
    fn area(&self) -> f64;
}

struct Circle {
    r: f64,
}

struct Square {
    side: f64,
}

impl Shape for Circle {
    fn area(&self) -> f64 {
        3.14 * self.r * self.r
    }
}

impl Shape for Square {
    fn area(&self) -> f64 {
        self.side * self.side
    }
}

fn make_square(side: f64) -> impl Shape {
    Square { side }
}

fn pick(round: bool, size: f64) -> Box<dyn Shape> {
    if round {
        Box::new(Circle { r: size })
    } else {
        Box::new(Square { side: size })
    }
}

fn main() {
    println!("impl Shape: {}", make_square(2.0).area());
    println!("Box, round: {:.2}", pick(true, 1.0).area());
    println!("Box, square: {:.2}", pick(false, 1.0).area());
}

