trait State {
    fn name(&self) -> &'static str;
    fn arrive(self: Box<Self>) -> Box<dyn State>;
    fn collect(self: Box<Self>) -> Box<dyn State>;
}

struct Requested;
struct OnHoldShelf;
struct Collected;

impl State for Requested {
    fn name(&self) -> &'static str {
        "requested"
    }
    fn arrive(self: Box<Self>) -> Box<dyn State> {
        Box::new(OnHoldShelf)
    }
    fn collect(self: Box<Self>) -> Box<dyn State> {
        self
    }
}

impl State for OnHoldShelf {
    fn name(&self) -> &'static str {
        "on the hold shelf"
    }
    fn arrive(self: Box<Self>) -> Box<dyn State> {
        self
    }
    fn collect(self: Box<Self>) -> Box<dyn State> {
        Box::new(Collected)
    }
}

impl State for Collected {
    fn name(&self) -> &'static str {
        "collected"
    }
    fn arrive(self: Box<Self>) -> Box<dyn State> {
        self
    }
    fn collect(self: Box<Self>) -> Box<dyn State> {
        self
    }
}

struct Hold {
    title: &'static str,
    state: Option<Box<dyn State>>,
}

impl Hold {
    fn new(title: &'static str) -> Hold {
        Hold { title, state: Some(Box::new(Requested)) }
    }
    fn status(&self) -> String {
        let stage = self.state.as_ref().unwrap();
        format!("{}: {}", self.title, stage.name())
    }
    fn arrive(&mut self) {
        if let Some(s) = self.state.take() {
            self.state = Some(s.arrive());
        }
    }
    fn collect(&mut self) {
        if let Some(s) = self.state.take() {
            self.state = Some(s.collect());
        }
    }
}

fn main() {
