trait Shape {
    fn area(&self) -> f64;
}

struct Circle {
    r: f64,
}

struct Square {
    side: f64,
}

impl Shape for Circle {
    fn area(&self) -> f64 {
        3.14 * self.r * self.r
    }
}

impl Shape for Square {
    fn area(&self) -> f64 {
        self.side * self.side
    }
}

fn total_static<T: Shape>(items: &[T]) -> f64 {
    items.iter().map(|s| s.area()).sum()
}

fn total_dynamic(items: &[Box<dyn Shape>]) -> f64 {
    items.iter().map(|s| s.area()).sum()
}

fn main() {
    let squares = [Square { side: 1.0 }, Square { side: 2.0 }];
    let circles = [Circle { r: 1.0 }];
    println!("static, squares only: {:.2}", total_static(&squares));
    println!("static, circles only: {:.2}", total_static(&circles));
    let mixed: Vec<Box<dyn Shape>> = vec![
        Box::new(Square { side: 1.0 }),
        Box::new(Circle { r: 1.0 }),
    ];
    println!("dynamic, mixed: {:.2}", total_dynamic(&mixed));
}

