use std::cell::RefCell;
use std::rc::{Rc, Weak};

struct Shelf {
    label: &'static str,
    books: RefCell<Vec<Rc<Book>>>,
}

struct Book {
    title: &'static str,
    shelf: RefCell<Weak<Shelf>>,
}

impl Drop for Shelf {
    fn drop(&mut self) {
        println!("shelf {} taken down", self.label);
    }
}

fn main() {
    let dune = Rc::new(Book {
        title: "Dune",
        shelf: RefCell::new(Weak::new()),
    });
    {
        let s = Rc::new(Shelf {
            label: "D",
            books: RefCell::new(vec![]),
        });
        s.books.borrow_mut().push(Rc::clone(&dune));
        *dune.shelf.borrow_mut() = Rc::downgrade(&s);
        let found = dune.shelf.borrow().upgrade();
        let label = found.map(|sh| sh.label).unwrap_or("?");
        println!("{} is on shelf {label}", dune.title);
        let (st, wk) = (Rc::strong_count(&s), Rc::weak_count(&s));
        println!("shelf: strong {st}, weak {wk}");
        println!("Dune: strong {}", Rc::strong_count(&dune));
    }
    let gone = dune.shelf.borrow().upgrade();
    let label = gone.map(|sh| sh.label);
    println!("{} is on shelf {label:?}", dune.title);
    println!("Dune: strong {}", Rc::strong_count(&dune));
}
